import math
S={'mode':'rev','af':None,'fd':0.0,'touch':0}

def wrap(a):
    return (a+180.0)%360.0-180.0

def clip(x,a):
    return max(-a,min(a,x))

def walls(obs):
    P=[]
    for k,v in (obs.get('views') or {}).items():
        if not v: continue
        try:
            ox,oy=v['origin']
            for w in v.get('walls',[]) or []:
                b,d=w[0],w[1]
                r=math.radians(b); P.append((ox+d*math.cos(r),oy+d*math.sin(r)))
        except Exception:
            pass
    return P

def corners(obs):
    vs=obs.get('views') or {}
    for k in ['camera','left_mirror','right_mirror','direct','periphery']:
        v=vs.get(k)
        if not v: continue
        try:
            tc=v.get('target_corners') or []
            if len(tc)>=2:
                ox,oy=v['origin']
                xs=[];ys=[]
                for c in tc:
                    b,d=c[0],c[1]; r=math.radians(b)
                    xs.append(ox+d*math.cos(r)); ys.append(oy+d*math.sin(r))
                return (sum(xs)/len(xs),sum(ys)/len(ys)),len(tc)
        except Exception:
            pass
    return None,0

def clearance(R,a,P,hw=1.15,cap=9.0):
    r=math.radians(a); ux,uy=math.cos(r),math.sin(r)
    c=cap
    for px,py in P:
        dx=px-R[0]; dy=py-R[1]
        al=dx*ux+dy*uy
        if al<=0: continue
        lat=abs(dx*uy-dy*ux)
        if lat<hw and al<c: c=al
    return c

def ff(p):
    s=math.sin(math.radians(p)); c=math.cos(math.radians(p))
    return math.degrees(math.atan(2.75*s/(2.6+1.05*c)))

def control(obs):
    LOOK=-23.0
    phi=obs.get('hitch_deg',0.0) or 0.0
    rig=obs['rig']; R=rig['trailer_rear']
    st=obs.get('status')
    dt=obs.get('dt',0.1) or 0.1
    v=obs.get('motion',{}).get('v_mps',0.0) or 0.0
    touches=obs.get('counters',{}).get('touches',0)
    P=walls(obs)
    if touches>S['touch'] or st in ('JACKKNIFED','PINNED') or abs(phi)>42:
        if S['mode']!='fwd':
            S['mode']='fwd'; S['fd']=0.0
            print('fwd at t=%.1f phi=%.1f st=%s'%(obs.get('t',0),phi,st))
    S['touch']=touches
    if S['mode']=='fwd':
        if v>0: S['fd']+=v*dt
        vf=rig.get('vehicle_front',3.6)
        block=False
        for px,py in P:
            if vf-0.1<px<vf+0.7 and abs(py)<1.2: block=True
        if (abs(phi)<6 and S['fd']>1.0) or S['fd']>3.0 or (block and S['fd']>0.3):
            S['mode']='rev'
        else:
            return (clip(-0.7*phi,28),1.0,LOOK)
    back=180.0-phi
    # gap seeking
    if P:
        best=-1;cands=[]
        for i in range(-22,23):
            a=back+3*i
            c=clearance(R,a,P)
            cands.append((a,c))
            if c>best: best=c
        good=[a for a,c in cands if c>=best-0.3]
        # contiguous run containing angle closest to back
        ga=min(good,key=lambda a:abs(wrap(a-back)))
        run=[ga]
        aset=set(round(a,3) for a in good)
        x=ga+3
        while round(x,3) in aset: run.append(x); x+=3
        x=ga-3
        while round(x,3) in aset: run.append(x); x-=3
        anew=sum(run)/len(run)
        if S['af'] is None: S['af']=anew
        else: S['af']=S['af']+0.35*wrap(anew-S['af'])
        curc=clearance(R,back,P)
    else:
        if S['af'] is None: S['af']=back
        curc=5.0
    aim=S['af']; cap=24.0; spd=-1.2; final=False
    T,n=corners(obs)
    if T is None:
        tg=obs.get('target') or {}
        if tg.get('in_sight') and tg.get('bearing_deg') is not None:
            ex,ey=rig['eye']; r=math.radians(tg['bearing_deg']); d=tg['dist_m']
            T=(ex+d*math.cos(r),ey+d*math.sin(r))
    if T is not None:
        dx=T[0]-R[0]; dy=T[1]-R[1]; dT=math.hypot(dx,dy)
        if dT<10 and dx<0:
            aim=math.degrees(math.atan2(dy,dx)); cap=10.0; spd=-0.8
            if dT<3.0:
                cap=4.0; spd=-0.6; final=True
    e=wrap(aim-back)
    phid=clip(-0.8*e,cap)
    steer=ff(phid)+2.2*(phi-phid)
    steer=clip(steer,34)
    if not final:
        if curc<3.0 or abs(phi-phid)>15: spd=max(spd,-0.8)
    return (steer,spd,LOOK)

