import math
C=(-8.35,-4.24); AX=-148.0
S={'ph':'fwd','fd':0.0,'fs':15.0,'X':0.0,'Y':0.0,'yaw':0.0,'woke':False,'touch':None,'n':0}

def wrap(a):
    return (a+180.0)%360.0-180.0

def clip(x,a):
    return max(-a,min(a,x))

def ff(p):
    s=math.sin(math.radians(p)); c=math.cos(math.radians(p))
    return math.degrees(math.atan(2.75*s/(2.6+1.05*c)))

def control(obs):
    dt=obs.get('dt',0.1) or 0.1
    m=obs.get('motion',{}) or {}
    v=m.get('v_mps',0.0) or 0.0
    st=obs.get('steer_deg',0.0) or 0.0
    S['yaw']+=v*math.tan(math.radians(st))/2.75*dt
    S['X']+=v*math.cos(S['yaw'])*dt
    S['Y']+=v*math.sin(S['yaw'])*dt
    phi=obs.get('hitch_deg',0.0) or 0.0
    rig=obs['rig']; R=rig['trailer_rear']
    c=math.cos(S['yaw']); s=math.sin(S['yaw'])
    Rw=(S['X']+c*R[0]-s*R[1], S['Y']+s*R[0]+c*R[1])
    back=math.degrees(S['yaw'])+180.0+rig.get('trailer_heading_deg',-phi)
    touches=obs.get('counters',{}).get('touches',0)
    if S['touch'] is None: S['touch']=touches
    if touches>S['touch'] or obs.get('status')=='JACKKNIFED' or abs(phi)>40:
        if S['ph']!='fwd':
            S['ph']='fwd'; S['fd']=0.0; S['fs']=clip(-0.7*phi,28)
            wake('pulling forward again phi=%.1f'%phi)
    S['touch']=touches
    if S['ph']=='fwd':
        if v>0: S['fd']+=v*dt
        if S['fd']>=1.0:
            S['ph']='rev'
        else:
            return (S['fs'],0.8,-23.0)
    ux=math.cos(math.radians(AX)); uy=math.sin(math.radians(AX))
    dx=Rw[0]-C[0]; dy=Rw[1]-C[1]
    along=dx*ux+dy*uy
    lat=ux*dy-uy*dx
    S['n']+=1
    if S['n']%10==0:
        print('t=%.1f along=%.2f lat=%.2f back=%.1f phi=%.1f'%(obs.get('t',0),along,lat,back,phi))
    if along>1.3:
        if not S['woke']:
            S['woke']=True; wake('reached end of planned line, stopped')
        return (0.0,0.0,-23.0)
    th=AX-clip(14.0*lat,28.0)
    e=wrap(th-back)
    phid=clip(-0.8*e,18.0)
    steer=clip(ff(phid)+2.2*(phi-phid),34.0)
    return (steer,-0.7,-23.0)

