import math
L=2.5; M=1.3; L2=3.6
S={'X':0.0,'Y':0.0,'T':0.0,'pts':{},'phase':'rev','fd':0.0,'need':0.0,'touch':0,'hd':0.0,'bay':None,'W':5.7,'cref':{},'lp':-10.0,'woke':0}
AS=(1.5,3.0,4.5,6.0,7.5)
def cl(x,a):
    return max(-a,min(a,x))
def w(px,py):
    c=math.cos(S['T']); s=math.sin(S['T'])
    return S['X']+c*px-s*py, S['Y']+s*px+c*py
def control(obs):
    dt=obs.get('dt',0.1) or 0.1
    m=obs.get('motion',{}) or {}
    v=m.get('v_mps',0.0) or 0.0
    sd=obs.get('steer_deg',0.0) or 0.0
    h=obs.get('hitch_deg',0.0) or 0.0
    t=obs.get('t',0.0) or 0.0
    S['T']+=v/L*math.tan(math.radians(sd))*dt
    S['X']+=v*math.cos(S['T'])*dt; S['Y']+=v*math.sin(S['T'])*dt
    views=obs.get('views') or {}
    if isinstance(views,dict):
        for name,vw in views.items():
            if not isinstance(vw,dict): continue
            o=vw.get('origin') or [0,0]
            for p in (vw.get('walls') or []):
                try:
                    b,d=float(p[0]),float(p[1])
                except Exception:
                    continue
                if d>14: continue
                px=o[0]+d*math.cos(math.radians(b)); py=o[1]+d*math.sin(math.radians(b))
                wx,wy=w(px,py)
                S['pts'][(round(wx/0.3),round(wy/0.3))]=(wx,wy)
    pts=S['pts']
    if len(pts)>3000:
        S['pts']={k:p for k,p in pts.items() if (p[0]-S['X'])**2+(p[1]-S['Y'])**2<400}
        pts=S['pts']
    rig=obs.get('rig') or {}
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('bearing_deg') is not None and tg.get('dist_m') is not None:
        e=rig.get('eye',[0.75,0])
        b=math.radians(tg['bearing_deg']); d=tg['dist_m']
        bx,by=w(e[0]+d*math.cos(b),e[1]+d*math.sin(b))
        if S['bay'] is None or d>3: 
            if S['bay'] is None: S['bay']=(bx,by)
            else:
                k=0.15 if d>8 else 0.3
                S['bay']=(S['bay'][0]*(1-k)+bx*k,S['bay'][1]*(1-k)+by*k)
    status=obs.get('status','')
    cnt=obs.get('counters') or {}
    tc=cnt.get('touches',0) or 0
    hold=m.get('hold_s',0) or 0
    look=64.0 if (t%3.2)<1.6 else -64.0
    if tc>S['touch']:
        S['touch']=tc; S['phase']='fwd'; S['fd']=0.0; S['need']=2.0
        try: wake('touch #%d h=%.1f'%(tc,h))
        except Exception: pass
    if status=='JACKKNIFED' or abs(h)>45:
        if S['phase']!='fwd':
            S['phase']='fwd'; S['fd']=0.0; S['need']=1.5
    if S['phase']=='fwd':
        if v>0: S['fd']+=v*dt
        if S['fd']>=S['need'] and abs(h)<8:
            S['phase']='rev'
        else:
            return (cl(-2.0*h,45),0.8,look)
    # trailer frame
    th=math.radians(rig.get('trailer_heading_deg',-h))
    hit=rig.get('hitch',[-1.3,0])
    axv=(hit[0]+L2*math.cos(th+math.pi), hit[1]+L2*math.sin(th+math.pi))
    ax,ay=w(axv[0],axv[1])
    F=S['T']+th
    bx_,by_=math.cos(F+math.pi),math.sin(F+math.pi)
    lx_,ly_=math.cos(F+math.pi/2),math.sin(F+math.pi/2)
    loc=[]
    for p in pts.values():
        dx=p[0]-ax; dy=p[1]-ay
        al=dx*bx_+dy*by_
        if -1.0<al<9.0:
            loc.append((al,dx*lx_+dy*ly_))
    off=0.0
    bayal=None
    if S['bay'] is not None:
        dx=S['bay'][0]-ax; dy=S['bay'][1]-ay
        bayal=dx*bx_+dy*by_; baylat=dx*lx_+dy*ly_
    aims=[]
    for a in AS:
        cr=S['cref'].get(a,0.0)
        lf=None; rt=None
        for al,lt in loc:
            if abs(al-a)<1.0:
                if lt>cr+0.8 and (lf is None or lt<lf): lf=lt
                if lt<cr-0.8 and (rt is None or lt>rt): rt=lt
        c=None
        if lf is not None and rt is not None and 3.5<lf-rt<9:
            c=(lf+rt)/2; S['W']=0.97*S['W']+0.03*(lf-rt)
        elif lf is not None and lf-cr<5: c=lf-S['W']/2
        elif rt is not None and cr-rt<5: c=rt+S['W']/2
        if c is not None:
            S['cref'][a]=c
            aims.append((a,c))
        else:
            S['cref'][a]=cr*0.98
    if bayal is not None and 0.0<bayal<12 and aims:
        # offset of bay from corridor centre near the bay
        best=min(aims,key=lambda q:abs(q[0]-bayal))
        if abs(best[0]-bayal)<2.5:
            off=cl(baylat-best[1],1.2)
    if aims:
        A=sum(q[0] for q in aims)/len(aims)
        Yc=sum(q[1] for q in aims)/len(aims)+off
        Ld=math.hypot(A,Yc)
        al=math.atan2(Yc,A)
        kap=2*math.sin(al)/max(Ld,2.0)
        hn=math.degrees(math.atan(L2*kap))*1.3
        hn=cl(hn,30)
        S['hd']=0.7*S['hd']+0.3*hn
    else:
        S['hd']*=0.97
    hd=S['hd']
    hr=math.radians(h)
    deq=math.degrees(math.atan(L*math.sin(hr)/(L2+M*math.cos(hr))))
    steer=cl(deq+1.6*(h-hd),45)
    sp=-0.8
    if bayal is not None and bayal<5: sp=-0.5
    if t-S['lp']>2.0:
        S['lp']=t
        print('t%.1f h%.1f hd%.1f st%.1f aims%s off%.2f bay%s W%.2f'%(t,h,hd,steer,[(round(a,1),round(c,2)) for a,c in aims],off,None if bayal is None else round(bayal,1),S['W']))
    return (steer,sp,look)

