    if max(xs)-min(xs)<0.8: return None
    mx=sum(xs)/len(xs); my=sum(ys)/len(ys)
    sxx=sum((x-mx)**2 for x in xs); sxy=sum((x-mx)*(y-my) for x,y in zip(xs,ys))
    if sxx<1e-6: return None
    return math.degrees(math.atan(sxy/sxx))

