state={'mode':'fwd','d':0.0,'a':35.0,'yc':-0.6,'woke':0}

def clamp(v,a,b):
    return max(a,min(b,v))

def linfit(pts):
    if len(pts)<2: return None
    xs=[p[0] for p in pts]; ys=[p[1] for p in pts]
    if max(xs)-min(xs)<0.35: return None
    mx=sum(xs)/len(xs); my=sum(ys)/len(ys)
    sxx=sum((x-mx)**2 for x in xs)
    sxy=sum((x-mx)*(y-my) for x,y in zip(xs,ys))
    m=sxy/sxx
    return (m,my-m*mx)

def control(obs):
    try:
        h=obs.get('hitch_deg',0.0) or 0.0
        dt=obs.get('dt',0.1) or 0.1
        v=(obs.get('motion') or {}).get('v_mps',0.0) or 0.0
        st=obs.get('status')
        look=170
        rem=(obs.get('progress') or {}).get('remaining',3) or 3
        rig=obs.get('rig') or {}
        tr=rig.get('trailer_rear',[-1.6,0.0])
        xr,yr=tr[0],tr[1]
        if state['mode']=='rev' and (st in ('PINNED','JACKKNIFED') or abs(h)>50):
            state['mode']='fwd'; state['d']=0.0
        if state['mode']=='fwd':
            if v>0: state['d']+=v*dt
            if state['d']>=0.5:
                state['mode']='rev'
            else:
                return (0.0,0.35,look)
        a=state['a']; ta=math.tan(math.radians(a))
        views=obs.get('views') or {}
        left=[];right=[]
        for name,vw in views.items():
            if not vw: continue
            o=vw.get('origin',[0.1,0.0])
            for w in vw.get('walls',[]) or []:
                b,d=w[0],w[1]
                x=o[0]+d*math.cos(math.radians(b)); y=o[1]+d*math.sin(math.radians(b))
                if x<-3.5 or x>-0.3: continue
                thr=state['yc']+ta*(x-xr)
                if y>thr: left.append((x,y))
                else: right.append((x,y))
        fl=linfit(left); fr=linfit(right)
        angs=[]
        for f in (fl,fr):
            if f is not None:
                an=math.degrees(math.atan(f[0]))
                if -10<an<60: angs.append(an)
        if angs:
