import math
S={'mode':'fwd1','X':0.0,'Y':0.0,'th':0.0,'d':0.0,'cx':-3.2,'cy':-2.97,'pa':-143.0,'n':0,'woke':0}

def cl(v,a,b):
    return max(a,min(b,v))

def wrap(a):
    while a>180: a-=360
    while a<-180: a+=360
    return a

def control(obs):
    try:
        h=obs.get('hitch_deg',0.0) or 0.0
        dt=obs.get('dt',0.1) or 0.1
        mo=obs.get('motion') or {}
        v=mo.get('v_mps',0.0) or 0.0
        sd=obs.get('steer_deg',0.0) or 0.0
        st=obs.get('status')
        th=S['th']
        S['X']+=v*math.cos(th)*dt; S['Y']+=v*math.sin(th)*dt
        S['th']+=v*math.tan(math.radians(sd))/1.25*dt
        th=S['th']; c=math.cos(th); s=math.sin(th)
        look=-150
        if S['mode']=='fwd1':
            if v>0: S['d']+=v*dt
            if math.degrees(th)>=28 or S['d']>=1.15:
                S['mode']='rev'
            else:
                return (35.0,0.4,look)
        if S['mode']=='fwd2':
            if v>0: S['d']+=v*dt
            if S['d']>=0.5 and abs(h)<12:
                S['mode']='rev'
            else:
                return (cl(-0.8*h,-30,30) if abs(h)>20 else 0.0,0.4,look)
        if st in ('PINNED','JACKKNIFED') or abs(h)>45:
            S['mode']='fwd2'; S['d']=0.0
            return (0.0,0.4,look)
        tg=obs.get('target') or {}
        if tg.get('in_sight') and tg.get('bearing_deg') is not None and tg.get('dist_m'):
            b=math.radians(tg['bearing_deg']); dd=tg['dist_m']
            vx=0.1+dd*math.cos(b); vy=dd*math.sin(b)
            wx=S['X']+c*vx-s*vy; wy=S['Y']+s*vx+c*vy
            S['cx']=0.93*S['cx']+0.07*wx; S['cy']=0.93*S['cy']+0.07*wy
        rig=obs.get('rig') or {}
        tr=rig.get('trailer_rear',[-1.6,0.0])
        tx=S['X']+c*tr[0]-s*tr[1]; ty=S['Y']+s*tr[0]+c*tr[1]
        pa=math.radians(S['pa'])
        dx=math.cos(pa); dy=math.sin(pa)
        ox=tx-S['cx']; oy=ty-S['cy']
        along=-(ox*dx+oy*dy)
        e=ox*(-dy)+oy*dx
        e=-(ox*dy*-1+oy*dx*-1) if False else (ox*(dy)*-1+oy*dx)
        psi_t=wrap(math.degrees(th)+180.0-h)
        k=30.0 if along>0.6 else 12.0
        psi_des=S['pa']+cl(k*e,-28,28)
        herr=wrap(psi_des-psi_t)
        h_des=cl(-1.0*herr,-32,32)
        steer=cl(1.1*h_des+2.5*(h-h_des),-45,45)
        S['n']+=1
        if S['n']%40==1:
            print('al',round(along,2),'e',round(e,2),'pt',round(psi_t),'pd',round(psi_des),'h',round(h),'hd',round(h_des))
        if along<-0.7:
            if S['woke']==0:
                S['woke']=1; wake('past estimated bay centre')
            return (0.0,0.0,look)
        return (steer,-0.3,look)
    except Exception as ex:
        print('err',ex)
        return (0.0,0.0,-150)

