import math
S={'mode':'rev','aim':None,'lp':-10,'minfree':15}
def wrap(a):
    while a>180: a-=360
    while a<-180: a+=360
    return a
def clamp(x,a,b):
    return max(a,min(b,x))
def control(obs):
    t=obs['t']; phi=obs['hitch_deg']
    rig=obs['rig']; R=rig['trailer_rear']; th=rig['trailer_heading_deg']
    beta=th+180.0
    views=obs.get('views') or {}
    cam=views.get('camera')
    aim=None; minfree=S['minfree']
    if cam:
        ox,oy=cam['origin']
        pts=[(ox+d*math.cos(math.radians(b)),oy+d*math.sin(math.radians(b))) for b,d in cam.get('walls',[])]
        cs=cam.get('target_corners') or []
        cpts=[]
        for c in cs:
            try:
                b,d=c[0],c[1]
                cpts.append((ox+d*math.cos(math.radians(b)),oy+d*math.sin(math.radians(b))))
            except Exception:
                pass
        frees=[]
        for off in range(-60,61,4):
            g=math.radians(beta+off); ux,uy=math.cos(g),math.sin(g)
            f=15.0
            for px,py in pts:
                qx,qy=px-R[0],py-R[1]
                al=qx*ux+qy*uy; la=abs(qx*uy-qy*ux)
                if al>0.3 and la<1.6 and al<f: f=al
            frees.append((off,f))
        minfree=frees[15][1]
        if len(cpts)>=2:
            cx=sum(p[0] for p in cpts)/len(cpts); cy=sum(p[1] for p in cpts)/len(cpts)
            aim=math.degrees(math.atan2(cy-R[1],cx-R[0]))
        else:
            bi=max(range(len(frees)),key=lambda i: frees[i][1]-0.03*abs(frees[i][0]))
            fb=frees[bi][1]
            lo=bi; hi=bi
            while lo>0 and frees[lo-1][1]>=fb-0.5: lo-=1
            while hi<len(frees)-1 and frees[hi+1][1]>=fb-0.5: hi+=1
            aim=beta+(frees[lo][0]+frees[hi][0])/2.0
        S['minfree']=minfree
    if aim is not None:
        S['aim']=wrap(aim-beta)
    rel=S['aim'] if S['aim'] is not None else 0.0
    st=obs.get('status')
    if S['mode']=='rev' and (abs(phi)>50 or st=='JACKKNIFED'):
        S['mode']='fwd'; wake('pulling forward to straighten, hitch %.1f'%phi)
    if S['mode']=='fwd':
        if abs(phi)<12:
            S['mode']='rev'
        else:
            return (0.0,1.5,-41)
    phides=clamp(-1.2*rel,-35,35)
    deq=math.degrees(math.atan(3.9/10.2*math.sin(math.radians(phides))))
    steer=clamp(deq+1.5*(phi-phides),-42,42)
    sp=-1.2
    if minfree<4: sp=-0.7
    if t-S['lp']>3:
        S['lp']=t
        print('t%.0f phi%.1f rel%.1f phid%.1f st%.1f free%.1f prog%s'%(t,phi,rel,phides,steer,minfree,obs['progress'].get('covered')))
    return (steer,sp,-41)

